import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem86 qualifica pureza consumo e material sem alterar operacao ou titulo do par',()=>{for(const [id,titulo] of [['jABp2HpfTmQNwXsPgrYQ','Creatina Monohidratada Pura 500g Dark Lab Unidade'],['jffyLJv2cImsjfarZ1pi','Ventilador de Teto Ventisol Aires Inverter Aires Inverter 14222 Teto Bivolt'],['JWp7l6fsqNkkSsBCAosW','Tênis Masculino Couro Nobuck Casual Minimalista Urbano Top']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.comentario,/44,90|98,1%|100% de pureza|economia de 75%/i);if(id==='jABp2HpfTmQNwXsPgrYQ')assert.equal(x.titulo,titulo);}});
